save(103,dict(paragraphs=["Nisha Luthra is a poet, playwright and theatre director associated with Chandigarh. As founder and director of The Narrators Performing Arts Society, she works across staged stories, poetry and adaptations of books. Her Hindi collection Uns explores love and human relationships, while her theatre work includes writing and performing Drama Queen and directing literary adaptations for the stage.","In ‘Wandering in Time’, the speaker moves through memories, attachments and changing understandings of the self. Clocks and a suitcase give ordinary shapes to the passage of experience, while images of rain, sunsets and first encounters keep it fluid. The poem questions permanence and makes room for a life that unfolds at its own pace."],sources=[source('The Narrators — founder and organisation','https://thenarrators.in/',['Nisha Luthra founder/director','Poet and Uns author','Book adaptation and school theatre work']),source('The Narrators — theatre productions','https://thenarrators.in/theatre/',['Drama Queen written and performed by Nisha Luthra, directed by Sahib Singh','Staged literary adaptations and Chandigarh productions']),source('The Indian Express — Nisha Luthra discusses Uns','https://indianexpress.com/article/cities/chandigarh/book-nook-nisha-luthra-book-poetry-love-friendship-7802151/',['Hindi poetry collection Uns','Themes of love and relationships'],access='search_index_excerpt')],books=[dict(title='Uns',detail='Hindi poetry collection, 2022. The author discusses its themes in The Indian Express.',url='https://indianexpress.com/article/cities/chandigarh/book-nook-nisha-luthra-book-poetry-love-friendship-7802151/')],identity_match='Distinctive Narrators founder/director affiliation, Chandigarh and poetry/theatre practice agree across captured biography, organisation site and author interview.',poems_read=[dict(id=64,title='Wandering in Time',basis='Full English original: time, suitcase, memory, attachment/detachment, learning/unlearning, own pace and questioned permanence.')],limitations=['Organisation site contains template remnants and promotional health language; those claims excluded.','No therapeutic efficacy, professional clinical qualification or award claims added.','Translation counts vary by date; no count asserted.','Nikasha Luthra is a different author; The Flowers in Her Room not attributed to Nisha.','Book launch page direct fetch failed; Uns title independently supported by organisation home page and author interview.'],research_leads=[dict(url='https://www.babushahi.com/view-news.php?id=189276',access='search_index_excerpt',finding='2024 multilingual launch report; no exact translation count needed in narrative.')],next_action='Independent author/editor review of concise narrative and bibliography.'))
